  // ---------- Swap & Crypto
  const swapBox = (lab, cur, name, amt, sub, dec) => card(col(rowx(`<div style="flex:1;font-size:13px;color:var(--text-muted);font-weight:600">${lab}</div><span style="height:34px;padding:0 10px 0 4px;border-radius:999px;background:var(--surface-sunken);display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:600">${Flag(cur, 26)}${name}${I('ChevronDown', 14)}</span>`, 8) + Amt(amt, { size: 34, cur, dec, weight: 700 }) + `<div style="font-size:13px;color:var(--text-muted)">${sub}</div>`, 10), { pad: '16px' });
