  // ---------- Scan & QR
  const camTabs = `<div style="display:flex;padding:4px;gap:2px;border-radius:999px;background:rgba(255,255,255,.14);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);width:240px;margin:0 auto">${['Scan', 'My code'].map((x, i) => `<span style="flex:1;height:38px;border-radius:999px;display:grid;place-items:center;font-size:14px;font-weight:600;${i ? 'color:rgba(255,255,255,.75)' : 'background:#FFFFFF;color:#111018'}">${x}</span>`).join('')}</div>`;
